import{_ as a,o as t,c as r,a4 as o}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Mundana / Chaula source profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/20-mundana-profile.md","filePath":"reference/20-mundana-profile.md","lastUpdated":1788517140000}'),n={name:"reference/20-mundana-profile.md"};function d(s,e,i,c,l,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="mundana-chaula-source-profile" tabindex="-1">Mundana / Chaula source profile <a class="header-anchor" href="#mundana-chaula-source-profile" aria-label="Permalink to &quot;Mundana / Chaula source profile&quot;">​</a></h1><h2 id="authority-and-scope" tabindex="-1">Authority and scope <a class="header-anchor" href="#authority-and-scope" aria-label="Permalink to &quot;Authority and scope&quot;">​</a></h2><p>The first-head-shave profile is based on B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, Chapter VIII, “Post-natal ceremonies” / “Tonsure (Chowlam),” printed pages 22–23 (PDF pages 26–27):</p><p><a href="https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf" target="_blank" rel="noreferrer">https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf</a></p><p>Raman is a modern synthesis and secondary authority, not primary scripture. The election does not replace family sampradaya, priestly guidance, guardian consent, hygiene or child-safety requirements.</p><h2 id="rule-to-code-crosswalk" tabindex="-1">Rule-to-code crosswalk <a class="header-anchor" href="#rule-to-code-crosswalk" aria-label="Permalink to &quot;Rule-to-code crosswalk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source statement</th><th>Implementation</th><th>Treatment</th></tr></thead><tbody><tr><td>Perform in the 3rd or 5th year; not while the mother is pregnant</td><td><code>manual_checks</code></td><td>Age and pregnancy are not finder inputs and remain explicit prerequisites.</td></tr><tr><td>Guru and Shukra free from combustion</td><td><code>skip_on_combust</code></td><td>A combust Guru or Shukra rejects the day using computed engine state.</td></tr><tr><td>Bright fortnight gives longevity; dark fortnight affects health</td><td><code>allowed_pakshams: Shukla</code></td><td>Conservative child-facing automation admits only Shukla Paksha.</td></tr><tr><td>Seven Tithis are good</td><td><code>allowed_tithi_numbers</code></td><td>Only 2, 3, 5, 7, 10, 11 and 13 survive at slot time.</td></tr><tr><td>Nine Nakshatras favorable and six ordinary</td><td><code>allowed_nakshatras</code>; <code>prefer_nakshatras</code></td><td>Both groups survive; only the favorable group receives the disclosed +1 distinction.</td></tr><tr><td>Always perform in the forenoon</td><td><code>forenoon_only</code></td><td>A named Muhurta survives only when its full interval ends by local solar noon; Python and browser enforce the same boundary.</td></tr><tr><td>Monday, Wednesday, Thursday and Friday are good</td><td><code>allowed_varas</code></td><td>Other weekdays reject the day.</td></tr><tr><td>Seven rising Rasis are good; other Rasis need benefic Lagna; reject Kumbha absolutely</td><td><code>allowed_lagnas</code>; <code>manual_checks</code></td><td>Conservative automation admits the seven unconditionally good Rasis; exceptional chart judgment remains manual.</td></tr><tr><td>Detailed benefic/malefic house placements and vacant 8th</td><td><code>manual_checks</code></td><td>Full election-chart occupancy remains practitioner-reviewed.</td></tr><tr><td>Surya in the “tropic of Karkataka”</td><td><code>manual_checks</code></td><td>The edition&#39;s seasonal wording is disclosed for practitioner interpretation rather than silently mapped to a possibly incorrect solar-sign gate.</td></tr></tbody></table><h2 id="product-contract-and-limitations" tabindex="-1">Product contract and limitations <a class="header-anchor" href="#product-contract-and-limitations" aria-label="Permalink to &quot;Product contract and limitations&quot;">​</a></h2><p>Shared samskara exclusions, hard avoid windows, Tithi-family ranking, personal scoring and relative tiers are not established by this locator. MCP exposes <code>muhurta.mundana</code>, the Paksha/forenoon gates and every manual requirement; the browser consumes and enforces the same generated rule contract.</p>',9)])])}const m=a(n,[["render",d]]);export{p as __pageData,m as default};
